/* Cards */
.card {
    box-shadow: 0 0 10px 0 rgba(183, 192, 206, 0.2);
    -webkit-box-shadow: 0 0 10px 0 rgba(183, 192, 206, 0.2);
    -moz-box-shadow: 0 0 10px 0 rgba(183, 192, 206, 0.2);
    -ms-box-shadow: 0 0 10px 0 rgba(183, 192, 206, 0.2);
}
.card .card-body {
    padding: 1.5rem 1.5rem;
}
.card .card-body + .card-body {
    padding-top: 1rem;
}
.card .card-title {
    color: #000;
    margin-bottom: 1.2rem;
    text-transform: uppercase;
    font-size: 0.875rem;
    font-weight: 600;
}
.card .card-subtitle {
    font-weight: 400;
    margin-top: 0.625rem;
    margin-bottom: 0.625rem;
}
.card .card-description {
    margin-bottom: 0.875rem;
    font-weight: 400;
    color: #76838f;
}
.card.card-outline-success {
    border: 1px solid #10b759;
}
.card.card-outline-primary {
    border: 1px solid #727cf5;
}
.card.card-outline-warning {
    border: 1px solid #fbbc06;
}
.card.card-outline-danger {
    border: 1px solid #ff3366;
}
.card.card-rounded {
    border-radius: 5px;
}
.card.card-faded {
    background: #b5b0b2;
    border-color: #b5b0b2;
}
.card.card-circle-progress {
    color: #ffffff;
    text-align: center;
}
.card.card-img-holder {
    position: relative;
}
.card.card-img-holder .card-img-absolute {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
}
.card.card-weather .weather-daily .weather-day {
    opacity: 0.5;
    font-weight: 900;
}
.card.card-weather .weather-daily i {
    font-size: 20px;
}
.card.card-weather .weather-daily .weather-temp {
    margin-top: 0.5rem;
    margin-bottom: 0;
    opacity: 0.5;
    font-size: 0.75rem;
}

.card-group {
    box-shadow: 0 0 10px 0 rgba(183, 192, 206, 0.2);
}
.card-group .card {
    box-shadow: none;
}

.card-inverse-primary {
    background: rgba(114, 124, 245, 0.2);
    border: 1px solid #575eba;
    color: #575eba;
}

.card-inverse-secondary {
    background: rgba(121, 135, 161, 0.2);
    border: 1px solid #5c677a;
    color: #5c677a;
}

.card-inverse-success {
    background: rgba(16, 183, 89, 0.2);
    border: 1px solid #0c8b44;
    color: #0c8b44;
}

.card-inverse-info {
    background: rgba(102, 209, 209, 0.2);
    border: 1px solid #4e9f9f;
    color: #4e9f9f;
}

.card-inverse-warning {
    background: rgba(251, 188, 6, 0.2);
    border: 1px solid #bf8f05;
    color: #bf8f05;
}

.card-inverse-danger {
    background: rgba(255, 51, 102, 0.2);
    border: 1px solid #c2274e;
    color: #c2274e;
}

.card-inverse-light {
    background: rgba(236, 236, 236, 0.2);
    border: 1px solid #b3b3b3;
    color: #b3b3b3;
}

.card-inverse-dark {
    background: rgba(40, 47, 58, 0.2);
    border: 1px solid #1e242c;
    color: #1e242c;
}

.card-inverse-primary-muted {
    background: rgba(177, 207, 236, 0.2);
    border: 1px solid #879db3;
    color: #879db3;
