omponents/_accordions.scss","common/components/_badges.scss","common/components/_bootstrap-alert.scss","common/components/_breadcrumbs.scss","common/components/_buttons.scss","common/components/_cards.scss","common/components/_checkbox-radio.scss","common/components/_dashboard.scss","common/components/_dropdown.scss","common/components/_forms.scss","common/components/_icons.scss","common/components/_input-group.scss","common/components/_list-group.scss","common/components/_modal.scss","common/components/_pagination.scss","common/components/_popover.scss","common/components/_profile.scss","common/components/_tables.scss","common/components/_timeline.scss","common/components/_chat.scss","common/components/_faq.scss","common/components/_auth.scss","common/components/email/_inbox.scss","common/components/email/_email-read.scss","common/components/email/_email-compose.scss","light/components/plugin-overrides/_ace.scss","light/components/plugin-overrides/_apex-charts.scss","light/components/plugin-overrides/_bootstrap-datepicker.scss","light/components/plugin-overrides/_data-tables.scss","light/components/plugin-overrides/_dropify.scss","light/components/plugin-overrides/_dropzone.scss","light/components/plugin-overrides/_full-calendar.scss","light/components/plugin-overrides/_jquery-flot.scss","light/components/plugin-overrides/_peity.scss","light/components/plugin-overrides/_perfect-scrollbar.scss","light/components/plugin-overrides/_sweet-alert.scss","light/components/plugin-overrides/_select2.scss","light/components/plugin-overrides/_simplemde.scss","light/components/plugin-overrides/_tags-input.scss","light/components/plugin-overrides/_tempusdominus-bootstrap-4.scss","light/components/plugin-overrides/_tinymce.scss","light/components/plugin-overrides/_typeahead.scss","light/components/plugin-overrides/_wizard.scss"],"sourcesContent":["\n// Booststrap functions and variables\n@import '../../../node_modules/bootstrap/scss/functions';\n@import '../../../node_modules/bootstrap/scss/variables';\n\n// Template variables\n@import '../light/variables';\n@import './variables';\n\n// SCSS compass funtions\n@import '../../../node_modules/compass-mixins/lib/compass';\n@import '../../../node_modules/compass-mixins/lib/animate';\n\n// Bootstrap main SCSS\n@import '../../../node_modules/bootstrap/scss/bootstrap.scss';\n\n// Template mixins\n@import '../common/mixins/animation';\n@import '../common/mixins/badges';\n@import '../common/mixins/blockquote';\n@import '../common/mixins/breadcrumbs';\n@import '../common/mixins/buttons';\n@import '../common/mixins/cards';\n@import '../common/mixins/misc';\n@import '../common/mixins/no_ui_slider';\n@import '../common/mixins/pagination';\n@import '../common/mixins/popovers';\n@import '../common/mixins/tooltips';\n@import '../common/mixins/width';\n\n// Core stules\n@import '../common/background';\n@import '../common/reset';\n@import '../common/functions';\n@import '../common/fonts';\n// @import url('https://fonts.googleapis.com/css?family=Overpass:300,400,600,700,800');\n@import '../common/footer';\n@import '../common/misc';\n@import '../common/utilities';\n@import '../common/demo';\n@import '../common/typography';\n\n@import './vertical-wrapper';\n@import './navbar';\n@import './sidebar';\n@import './layouts';\n\n// components\n@import \"../common/components/accordions\";\n@import \"../common/components/badges\";\n@import \"../common/components/bootstrap-alert\";\n@import \"../common/components/breadcrumbs\";\n@import \"../common/components/buttons\";\n@import \"../common/components/cards\";\n@import \"../common/components/checkbox-radio\";\n@import \"../common/components/dashboard\";\n@import \"../common/components/dropdown\";\n@import \"../common/components/forms\";\n@import \"../common/components/icons\";\n@import \"../common/components/input-group\";\n@import \"../common/components/list-group\";\n@import \"../common/components/modal\";\n@import \"../common/components/pagination\";\n@import \"../common/components/popover\";\n@import \"../common/components/profile\";\n@import \"../common/components/tables\";\n@import \"../common/components/timeline\";\n@import \"../common/components/chat\";\n@import \"../common/components/faq\";\n@import \"../common/components/auth\";\n\n// Email\n@import '../common/components/email/inbox';\n@import '../common/components/email/email-read';\n@import '../common/components/email/email-compose';\n\n\n// Plugin overrides\n@import \"../light/components/plugin-overrides/ace\";\n@import \"../light/components/plugin-overrides/apex-charts\";\n@import \"../light/components/plugin-overrides/bootstrap-datepicker\";\n@import \"../light/components/plugin-overrides/data-tables\";\n@import \"../light/components/plugin-overrides/dropify\";\n@import \"../light/components/plugin-overrides/dropzone\";\n@import \"../light/components/plugin-overrides/full-calendar\";\n@import \"../light/components/plugin-overrides/jquery-flot\";\n@import \"../light/components/plugin-overrides/peity\";\n@import \"../light/components/plugin-overrides/perfect-scrollbar\";\n@import \"../light/components/plugin-overrides/sweet-alert\";\n@import \"../light/components/plugin-overrides/select2\";\n@import \"../light/components/plugin-overrides/simplemde\";\n@import \"../light/components/plugin-overrides/tags-input\";\n@import \"../light/components/plugin-overrides/tempusdominus-bootstrap-4\";\n@import \"../light/components/plugin-overrides/tinymce\";\n@import \"../light/components/plugin-overrides/typeahead\";\n@import \"../light/components/plugin-overrides/wizard\";\n\n\n","// Bootstrap functions\n//\n// Utility mixins and functions for evaluating source code across our variables, maps, and mixins.\n\n// Ascending\n// Used to evaluate Sass maps like our grid breakpoints.\n@mixin _assert-ascending($map, $map-name) {\n  $prev-key: null;\n  $prev-num: null;\n  @each $key, $num in $map {\n    @if $prev-num == null or unit($num) == \"%\" or unit($prev-num) == \"%\" {\n      // Do nothing\n    } @else if not comparable($prev-num, $num) {\n      @warn \"Potentially invalid value for #{$map-name}: This map must be in ascending order, but key '#{$key}' has value #{$num} whose unit makes it incomparable to #{$prev-num}, the value of the previous key '#{$prev-key}' !\";\n    } @else if $prev-num >= $num {\n      @warn \"Invalid value for #{$map-name}: This map must be in ascending order, but key '#{$key}' has value #{$num} which isn't greater than #{$prev-num}, the value of the previous key '#{$prev-key}' !\";\n    }\n    $prev-key: $key;\n    $prev-num: $num;\n  }\n}\n\n// Starts at zero\n// Used to ensure the min-width of the lowest breakpoint starts at 0.\n@mixin _assert-starts-at-zero($map, $map-name: \"$grid-breakpoints\") {\n  @if length($map) > 0 {\n    $values: map-values($map);\n    $first-value: nth($values, 1);\n    @if $first-value != 0 {\n      @warn \"First breakpoint in #{$map-name} must start at 0, but starts at #{$first-value}.\";\n    }\n  }\n}\n\n// Replace `$search` with `$replace` in `$string`\n// Used on our SVG icon backgrounds for custom forms.\n//\n// @author Hugo Giraudel\n// @param {String} $string - Initial string\n// @param {String} $search - Substring to replace\n// @param {String} $replace ('') - New value\n// @return {String} - Updated string\n@function str-replace($string, $search, $replace: \"\") {\n  $index: str-index($string, $search);\n\n  @if $index {\n    @return str-slice($string, 1, $index - 1) + $replace + str-replace(str-slice($string, $index + str-length($search)), $search, $replace);\n  }\n\n  @return $string;\n}\n\n// See https://codepen.io/kevinweber/pen/dXWoRw\n@function escape-svg($string) {\n  @if str-index($string, \"data:image/svg+xml\") {\n    @each $char, $encoded in $escaped-characters {\n      // Do not escape the url brackets\n      @if str-index($string, \"url(\") == 1 {\n        $string: url(\"#{str-replace(str-slice($string, 6, -3), $char, $encoded)}\");\n      } @else {\n        $string: str-replace($string, $char, $encoded);\n      }\n    }\n  }\n\n  @return $string;\n}\n\n// Color contrast\n@function color-yiq($color, $dark: $yiq-text-dark, $light: $yiq-text-light) {\n  $r: red($color);\n  $g: green($color);\n  $b: blue($color);\n\n  $yiq: (($r * 299) + ($g * 587) + ($b * 114)) / 1000;\n\n  @if ($yiq >= $yiq-contrasted-threshold) {\n    @return $dark;\n  } @else {\n    @return $light;\n  }\n}\n\n// Retrieve color Sass maps\n@function color($key: \"blue\") {\n  @return map-get($colors, $key);\n}\n\n@function theme-color($key: \"primary\") {\n  @return map-get($theme-colors, $key);\n}\n\n@function gray($key: \"100\") {\n  @return map-get($grays, $key);\n}\n\n// Request a theme color level\n@function theme-color-level($color-name: \"primary\", $level: 0) {\n  $color: theme-color($color-name);\n  $color-base: if($level > 0, $black, $white);\n  $level: abs($level);\n\n  @return mix($color-base, $color, $level * $theme-color-interval);\n}\n\n// Return valid calc\n@function add($value1, $value2, $return-calc: true) {\n  @if $value1 == null {\n    @return $value2;\n  }\n\n  @if $value2 == null {\n    @return $value1;\n  }\n\n  @if type-of($value1) == number and type-of($value2) == number and comparable($value1, $value2) {\n    @return $value1 + $value2;\n  }\n\n  @return if($return-calc == true, calc(#{$value1} + #{$value2}), $value1 + unquote(\" + \") + $value2);\n}\n\n@function subtract($value1, $value2, $return-calc: true) {\n  @if $value1 == null and $value2 == null {\n    @return null;\n  }\n\n  @if $value1 == null {\n    @return -$value2;\n  }\n\n  @if $value2 == null {\n    @return $value1;\n  }\n\n  @if type-of($value1) == number and type-of($value2) == number and comparable($value1, $value2) {\n    @return $value1 - $value2;\n  }\n\n  @return if($return-calc == true, calc(#{$value1} - #{$value2}), $value1 + unquote(\" - \") + $value2);\n}\n","// Variables\n//\n// Variables should follow the `$component-state-property-size` formula for\n// consistent naming. Ex: $nav-link-disabled-color and $modal-content-box-shadow-xs.\n\n// Color system\n\n$white:    #fff !default;\n$gray-100: #f8f9fa !default;\n$gray-200: #e9ecef !default;\n$gray-300: #dee2e6 !default;\n$gray-400: #ced4da !default;\n$gray-500: #adb5bd !default;\n$gray-600: #6c757d !default;\n$gray-700: #495057 !default;\n$gray-800: #343a40 !default;\n$gray-900: #212529 !default;\n$black:    #000 !default;\n\n$grays: () !default;\n// stylelint-disable-next-line scss/dollar-variable-default\n$grays: map-merge(\n  (\n    \"100\": $gray-100,\n    \"200\": $gray-200,\n    \"300\": $gray-300,\n    \"400\": $gray-400,\n    \"500\": $gray-500,\n    \"600\": $gray-600,\n    \"700\": $gray-700,\n    \"800\": $gray-800,\n    \"900\": $gray-900\n  ),\n  $grays\n);\n\n$blue:    #007bff !default;\n$indigo:  #6610f2 !default;\n$purple:  #6f42c1 !default;\n$pink:    #e83e8c !default;\n$red:     #dc3545 !default;\n$orange:  #fd7e14 !default;\n$yellow:  #ffc107 !default;\n$green:   #28a745 !default;\n$teal:    #20c997 !default;\n$cyan:    #17a2b8 !default;\n\n$colors: () !default;\n// stylelint-disable-next-line scss/dollar-variable-default\n$colors: map-merge(\n  (\n    \"blue\":       $blue,\n    \"indigo\":     $indigo,\n    \"purple\":     $purple,\n    \"pink\":       $pink,\n    \"red\":        $red,\n    \"orange\":     $orange,\n    \"yellow\":     $yellow,\n    \"green\":      $green,\n    \"teal\":       $teal,\n    \"cyan\":       $cyan,\n    \"white\":      $white,\n    \"gray\":       $gray-600,\n    \"gray-dark\":  $gray-800\n  ),\n  $colors\n);\n\n$primary:       $blue !default;\n$secondary:     $gray-600 !default;\n$success:       $green !default;\n$info:          $cyan !default;\n$warning:       $yellow !default;\n$danger:        $red !default;\n$light:         $gray-100 !default;\n$dark:          $gray-800 !default;\n\n$theme-colors: () !default;\n// stylelint-disable-next-line scss/dollar-variable-default\n$theme-colors: map-merge(\n  (\n    \"primary