t read by a screen reader.\n@mixin squish-text {\n  font: 0/0 serif;\n  text-shadow: none;\n  color: transparent;\n}\n","// Prevent long urls and text from breaking layouts\n// [originally from perishablepress.com](http://perishablepress.com/press/2010/06/01/wrapping-content/)\n@mixin force-wrap {\n  white-space: pre;           // CSS 2.0\n  white-space: pre-wrap;      // CSS 2.1\n  white-space: pre-line;      // CSS 3.0\n  white-space: -pre-wrap;     // Opera 4-6\n  white-space: -o-pre-wrap;   // Opera 7\n  white-space: -moz-pre-wrap; // Mozilla\n  white-space: -hp-pre-wrap;  // HP Printers\n  word-wrap: break-word;      // IE 5+\n}\n","@import \"typography/links\";\n@import \"typography/lists\";\n@import \"typography/text\";\n@import \"typography/vertical_rhythm\";\n","@import \"../layout/grid-background\";\n\n// The base font size.\n$base-font-size: 16px !default;\n\n// The base line height determines the basic unit of vertical rhythm.\n$base-line-height: 24px !default;\n\n// Set the default border style for rhythm borders.\n$default-rhythm-border-style: solid !default;\n\n// The default font size in all browsers.\n$browser-default-font-size: 16px;\n\n// Set to false if you want to use absolute pixels in sizing your typography.\n$relative-font-sizing: true !default;\n\n// Allows the `adjust-font-size-to` mixin and the `lines-for-font-size` function\n// to round the line height to the nearest half line height instead of the\n// nearest integral line height to avoid large spacing between lines.\n$round-to-nearest-half-line: false !default;\n\n// Ensure there is at least this many pixels\n// of vertical padding above and below the text.\n$min-line-padding: 2px !default;\n\n// $base-font-size but in your output unit of choice.\n// Defaults to 1em when `$relative-font-sizing` is true.\n$font-unit: if($relative-font-sizing, 1em, $base-font-size) !default;\n\n// The basic unit of font rhythm.\n$base-rhythm-unit: $base-line-height / $base-font-size * $font-unit;\n\n// The leader is the amount of whitespace in a line.\n// It might be useful in your calculations.\n$base-leader: ($base-line-height - $base-font-size) * $font-unit / $base-font-size;\n\n// The half-leader is the amount of whitespace above and below a line.\n// It might be useful in your calculations.\n$base-half-leader: $base-leader / 2;\n\n// True if a number has a relative unit.\n@function relative-unit($number) {\n  @return unit($number) == \"%\" or unit($number) == \"em\" or unit($number) == \"rem\"\n}\n\n// True if a number has an absolute unit.\n@function absolute-unit($number) {\n  @return not(relative-unit($number) or unitless($number));\n}\n\n@if $relative-font-sizing and not(relative-unit($font-unit)) {\n  @warn \"$relative-font-sizing is true but $font-unit is set to #{$font-unit} which is not a relative unit.\";\n}\n\n// Establishes a font baseline for the given font-size.\n@mixin establish-baseline($font-size: $base-font-size) {\n  // IE 6 refuses to resize fonts set in pixels and it weirdly resizes fonts\n  // whose root is set in ems. So we set the root font size in percentages of\n  // the default font size.\n  * html {\n    font-size: 100% * ($font-size / $browser-default-font-size);\n  }\n  html {\n    font-size: $font-size;\n    @include adjust-leading-to(1, if($relative-font-sizing, $font-size, $base-font-size));\n  }\n}\n\n// Resets the line-height to 1 vertical rhythm unit.\n// Does not work on elements whose font-size is different from $base-font-size.\n//\n// @deprecated This mixin will be removed in the next release.\n// Please use the `adjust-leading-to` mixin instead.\n@mixin reset-baseline {\n  @include adjust-leading-to(1, if($relative-font-sizing, $base-font-size, $base-font-size));\n}\n\n// Show a background image that can be used to debug your alignments.\n// Include the $img argument if you would rather use your own image than the\n// Compass default gradient image.\n@mixin debug-vertical-alignment($img: false) {\n  @if $img {\n    background: image-url($img);\n  } @else {\n    @include baseline-grid-background($base-rhythm-unit);\n  }\n}\n\n// Adjust a block to have a different font size and line height to maintain the\n// rhythm. $lines specifies how many multiples of the baseline rhythm each line\n// of this font should use up. It does not have to be an integer, but it\n// defaults to the smallest integer that is large enough to fit the font.\n// Use $from-size to adjust from a font-size other than the base font-size.\n@mixin adjust-font-size-to($to-size, $lines: lines-for-font-size($to-size), $from-size: $base-font-size) {\n  @if not($relative-font-sizing) and $from-size != $base-font-size {\n    @warn \"$relative-font-sizing is false but a relative font size was passed to adjust-font-size-to\";\n  }\n  font-size: $font-unit * $to-size / $from-size;\n  @include adjust-leading-to($lines, if($relative-font-sizing, $to-size, $base-font-size));\n}\n\n// Adjust a block to have different line height to maintain the rhythm.\n// $lines specifies how many multiples of the baseline rhythm each line of this\n// font should use up. It does not have to be an integer, but it defaults to the\n// smallest integer that is large enough to fit the font.\n@mixin adjust-leading-to($lines, $font-size: $base-font-size) {\n  line-height: rhythm($lines, $font-size);\n}\n\n// Calculate rhythm units.\n@function rhythm(\n  $lines: 1,\n  $font-size: $base-font-size,\n  $offset: 0\n) {\n  @if not($relative-font-sizing) and $font-size != $base-font-size {\n    @warn \"$relative-font-sizing is false but a relative font size was passed to the rhythm function\";\n  }\n  $rhythm: $font-unit * ($lines * $base-line-height - $offset) / $font-size;\n  // Round the pixels down to nearest integer.\n  @if unit($rhythm) == px {\n    $rhythm: floor($rhythm);\n  }\n  @return $rhythm;\n}\n\n// Calculate the minimum multiple of rhythm units needed to contain the font-size.\n@function lines-for-font-size($font-size) {\n  $lines: if($round-to-nearest-half-line,\n              ceil(2 * $font-size / $base-line-height) / 2,\n              ceil($font-size / $base-line-height));\n  @if $lines * $base-line-height - $font-size < $min-line-padding * 2 {\n    $lines: $lines + if($round-to-nearest-half-line, 0.5, 1);\n  }\n  @return $lines;\n}\n\n// Apply leading whitespace. The $property can be margin or padding.\n@mixin leader($lines: 1, $font-size: $base-font-size, $property: margin) {\n  #{$property}-top: rhythm($lines, $font-size);\n}\n\n// Apply leading whitespace as padding.\n@mixin padding-leader($lines: 1, $font-size: $base-font-size) {\n  padding-top: rhythm($lines, $font-size);\n}\n\n// Apply leading whitespace as margin.\n@mixin margin-leader($lines: 1, $font-size: $base-font-size) {\n  margin-top: rhythm($lines, $font-size);\n}\n\n// Apply trailing whitespace. The $property can be margin or padding.\n@mixin trailer($lines: 1, $font-size: $base-font-size, $property: margin) {\n  #{$property}-bottom: rhythm($lines, $font-size);\n}\n\n// Apply trailing whitespace as padding.\n@mixin padding-trailer($lines: 1, $font-size: $base-font-size) {\n  padding-bottom: rhythm($lines, $font-size);\n}\n\n// Apply trailing whitespace as margin.\n@mixin margin-trailer($lines: 1, $font-size: $base-font-size) {\n  margin-bottom: rhythm($lines, $font-size);\n}\n\n// Shorthand mixin to apply whitespace for top and bottom margins and padding.\n@mixin rhythm($leader: 0, $padding-leader: 0, $padding-trailer: 0, $trailer: 0, $font-size: $base-font-size) {\n  @include leader($leader, $font-size);\n  @include padding-leader($padding-leader, $font-size);\n  @include padding-trailer($padding-trailer, $font-size);\n  @include trailer($trailer, $font-size);\n}\n\n// Apply a border and whitespace to any side without destroying the vertical\n// rhythm. The whitespace must be greater than the width of the border.\n@mixin apply-side-rhythm-border($side, $width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @if not($relative-font-sizing) and $font-size != $base-font-size {\n    @warn \"$relative-font-sizing is false but a relative font size was passed to apply-side-rhythm-border\";\n  }\n  border-#{$side}-style: $border-style;\n  border-#{$side}-width: $font-unit * $width / $font-size;\n  padding-#{$side}: rhythm($lines, $font-size, $offset: $width);\n}\n\n// Apply borders and whitespace equally to all sides.\n@mixin rhythm-borders($width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @if not($relative-font-sizing) and $font-size != $base-font-size {\n    @warn \"$relative-font-sizing is false but a relative font size was passed to rhythm-borders\";\n  }\n  border: {\n    style: $border-style;\n    width: $font-unit * $width / $font-size;\n  };\n  padding: rhythm($lines, $font-size, $offset: $width);\n}\n\n// Apply a leading border.\n@mixin leading-border($width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @include apply-side-rhythm-border(top, $width, $lines, $font-size, $border-style);\n}\n\n// Apply a trailing border.\n@mixin trailing-border($width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @include apply-side-rhythm-border(bottom, $width, $lines, $font-size, $border-style);\n}\n\n// Apply both leading and trailing borders.\n@mixin horizontal-borders($width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @include leading-border($width, $lines, $font-size, $border-style);\n  @include trailing-border($width, $lines, $font-size, $border-style);\n}\n\n// Alias for `horizontal-borders` mixin.\n@mixin h-borders($width: 1px, $lines: 1, $font-size: $base-font-size, $border-style: $default-rhythm-border-style) {\n  @include horizontal-borders($width, $lines, $font-size, $border-style);\n}\n","@import \"../css3/images\";\n@import \"../css3/background-size\";\n\n// Set the color of your columns\n$grid-background-column-color     : rgba(100, 100, 225, 0.25)   !default;\n// Set the color of your gutters\n$grid-background-gutter-color     : rgba(0, 0, 0, 0)            !default;\n\n// Set the total number of columns in your grid\n$grid-background-total-columns    : 24                          !default;\n// Set the width of your columns\n$grid-background-column-width     : 30px                        !default;\n// Set the width of your gutters\n$grid-background-gutter-width     : 10px                        !default;\n// Set the offset, if your columns are padded in from the container edge\n$grid-background-offset           : 0px                         !default;\n\n// Set the color of your baseline\n$grid-background-baseline-color   : rgba(0, 0, 0, 0.5)          !default;\n// Set the height of your baseline grid\n$grid-background-baseline-height  : 1.5em                       !default;\n\n// toggle your columns grids on and off\n$show-column-grid-backgrounds     : true                        !default;\n// toggle your vertical grids on and off\n$show-baseline-grid-backgrounds   : true                        !default;\n// toggle all your grids on and off\n$show-grid-backgrounds            : true                        !default;\n\n// optionally force your grid-image to remain fluid\n// no matter what units you used to declared your grid.\n$grid-background-force-fluid      : false                       !default;\n\n\n// Create the gradient needed for baseline grids\n@function get-baseline-gradient(\n  $color : $grid-background-baseline-color\n) {\n  $gradient: linear-gradient(bottom, $color 5%, rgba($color,0) 5%);\n  @return $gradient;\n}\n\n// Create the color-stops needed for horizontal grids\n@function build-grid-background(\n  $total          : $grid-background-total-columns,\n  $column         : $grid-background-column-width,\n  $gutter         : $grid-background-gutter-width,\n  $offset         : $grid-background-offset,\n