lor, horizontal offset, vertical offset, blur, and spread\n// according to the configuration defaults above.\n@mixin single-text-shadow(\n  $hoff: false,\n  $voff: false,\n  $blur: false,\n  $spread: false,\n  $color: false\n) {\n  // A lot of people think the color comes first. It doesn't.\n  @if type-of($hoff) == color {\n    $temp-color: $hoff;\n    $hoff: $voff;\n    $voff: $blur;\n    $blur: $spread;\n    $spread: $color;\n    $color: $temp-color;\n  }\n  // Can't rely on default assignment with multiple supported argument orders.\n  $hoff:   if($hoff,   $hoff,   $default-text-shadow-h-offset);\n  $voff:   if($voff,   $voff,   $default-text-shadow-v-offset);\n  $blur:   if($blur,   $blur,   $default-text-shadow-blur    );\n  $spread: if($spread, $spread, $default-text-shadow-spread  );\n  $color:  if($color,  $color,  $default-text-shadow-color   );\n  // We don't need experimental support for this property.\n  @if $color == none or $hoff == none {\n    @include text-shadow(none);\n  } @else {\n    @include text-shadow(compact($hoff $voff $blur $spread $color));\n  }\n}\n","@import \"shared\";\n\n// Specify the shorthand `columns` property.\n//\n// Example:\n//\n//     @include columns(20em 2)\n@mixin columns($width-and-count) {\n  @include experimental(columns, $width-and-count,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the number of columns\n@mixin column-count($count) {\n  @include experimental(column-count, $count,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the gap between columns e.g. `20px`\n@mixin column-gap($width) {\n  @include experimental(column-gap, $width,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the width of columns e.g. `100px`\n@mixin column-width($width) {\n  @include experimental(column-width, $width,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the width of the rule between columns e.g. `1px`\n@mixin column-rule-width($width) {\n  @include experimental(column-rule-width, $width,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the style of the rule between columns e.g. `dotted`.\n// This works like border-style.\n@mixin column-rule-style($style) {\n  @include experimental(column-rule-style, unquote($style),\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Specify the color of the rule between columns e.g. `blue`.\n// This works like border-color.\n@mixin column-rule-color($color) {\n  @include experimental(column-rule-color, $color,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Mixin encompassing all column rule properties\n// For example:\n//\n//     @include column-rule(1px, solid, #c00)\n//\n// Or the values can be space separated:\n//\n//     @include column-rule(1px solid #c00)\n@mixin column-rule($width, $style: false, $color: false) {\n  $full : -compass-space-list(compact($width, $style, $color));\n  @include experimental(column-rule, $full,\n    -moz, -webkit, -o, -ms, not(-khtml), official\n  );\n}\n\n// Mixin for setting column-break-before\n//\n// * legal values are auto, always, avoid, left, right, page, column, avoid-page, avoid-column\n//\n//  Example: \n//    h2.before {@include column-break-before(always);}\n//\n//  Which generates: \n//\n//  h2.before {    \n//    -webkit-column-break-before: always;\n//    column-break-before: always;}\n@mixin column-break-before($value: auto){\n   @include experimental(column-break-before, $value, not(-moz), -webkit, not(-o), not(-ms), not(-khtml), official );\n}\n\n// Mixin for setting column-break-after\n//\n// * legal values are auto, always, avoid, left, right, page, column, avoid-page, avoid-column\n//\n//  Example: \n//    h2.after {@include column-break-after(always); }\n//\n//  Which generates: \n//\n//  h2.after {\n//    -webkit-column-break-after: always;\n//    column-break-after: always; }\n@mixin column-break-after($value: auto){\n   @include experimental(column-break-after, $value, not(-moz), -webkit, not(-o), not(-ms), not(-khtml), official );\n}\n\n// Mixin for setting column-break-inside\n//\n// * legal values are auto, avoid, avoid-page, avoid-column\n//\n//  Example: \n//    h2.inside {@include column-break-inside();}\n//  Which generates: \n//  \n//  h2.inside {\n//    -webkit-column-break-inside: auto;\n//    column-break-inside: auto;}\n@mixin column-break-inside($value: auto){\n   @include experimental(column-break-inside, $value, not(-moz), -webkit, not(-o), not(-ms), not(-khtml), official );\n}\n\n// All-purpose mixin for setting column breaks.\n//\n// * legal values for $type : before, after, inside \n// * legal values for '$value' are dependent on $type\n//    * when $type = before, legal values are auto, always, avoid, left, right, page, column, avoid-page, avoid-column\n//    * when $type = after, legal values are auto, always, avoid, left, right, page, column, avoid-page, avoid-column\n//    * when $type = inside, legal values are auto, avoid, avoid-page, avoid-column\n//  \n//  Examples: \n//    h2.before {@include column-break(before, always);}\n//    h2.after {@include column-break(after, always); }\n//    h2.inside {@include column-break(inside); }\n//\n//  Which generates: \n//  h2.before {    \n//    -webkit-column-break-before: always;\n//    column-break-before: always;}\n//  \n//  h2.after {\n//    -webkit-column-break-after: always;\n//    column-break-after: always; }\n//\n//  h2.inside {\n//    -webkit-column-break-inside: auto;\n//    column-break-inside: auto;}\n \n@mixin column-break($type: before, $value: auto){\n   @include experimental(\"column-break-#{$type}\", $value, not(-moz), -webkit, not(-o), not(-ms), not(-khtml), official );\n}","@import \"shared\";\n\n// Change the box model for Mozilla, Webkit, IE8 and the future\n//\n// @param $bs\n//   [ content-box | border-box ]\n\n@mixin box-sizing($bs) {\n  $bs: unquote($bs);\n  @include experimental(box-sizing, $bs,\n    -moz, -webkit, not(-o), not(-ms), not(-khtml), official\n  );\n}\n","@import \"shared\";\n\n// display:box; must be used for any of the other flexbox mixins to work properly\n@mixin display-box {\n  @include experimental-value(display, box,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// Default box orientation, assuming that the user wants something less block-like\n$default-box-orient: horizontal !default;\n\n// Box orientation [ horizontal | vertical | inline-axis | block-axis | inherit ]\n@mixin box-orient(\n  $orientation: $default-box-orient\n) {\n  $orientation : unquote($orientation);\n  @include experimental(box-orient, $orientation,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// Default box-align\n$default-box-align: stretch !default;\n\n// Box align [ start | end | center | baseline | stretch ]\n@mixin box-align(\n  $alignment: $default-box-align\n) {\n  $alignment : unquote($alignment);\n  @include experimental(box-align, $alignment,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// Default box flex\n$default-box-flex: 0 !default;\n\n// mixin which takes an int argument for box flex. Apply this to the children inside the box.\n//\n// For example: \"div.display-box > div.child-box\" would get the box flex mixin.\n@mixin box-flex(\n  $flex: $default-box-flex\n) {\n  @include experimental(box-flex, $flex,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// Default flex group\n$default-box-flex-group: 1 !default;\n\n// mixin which takes an int argument for flexible grouping\n@mixin box-flex-group(\n  $group: $default-box-flex-group\n) {\n  @include experimental(box-flex-group, $group,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// default for ordinal group\n$default-box-ordinal-group: 1 !default;\n\n// mixin which takes an int argument for ordinal grouping and rearranging the order\n@mixin box-ordinal-group(\n  $group: $default-ordinal-flex-group\n) {\n  @include experimental(box-ordinal-group, $group,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// Box direction default value\n$default-box-direction: normal !default;\n\n// mixin for box-direction [ normal | reverse | inherit ]\n@mixin box-direction(\n  $direction: $default-box-direction\n) {\n  $direction: unquote($direction);\n  @include experimental(box-direction, $direction,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// default for box lines\n$default-box-lines: single !default;\n\n// mixin for box lines [ single | multiple ]\n@mixin box-lines(\n  $lines: $default-box-lines\n) {\n  $lines: unquote($lines);\n  @include experimental(box-lines, $lines,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}\n\n// default for box pack\n$default-box-pack: start !default;\n\n// mixin for box pack [ start | end | center | justify ]\n@mixin box-pack(\n  $pack: $default-box-pack\n) {\n  $pack: unquote($pack);\n  @include experimental(box-pack, $pack,\n    -moz, -webkit, not(-o), -ms, not(-khtml), official\n  );\n}","@import \"shared\";\n\n// The default value is `padding-box` -- the box model used by modern browsers.\n//\n// If you wish to do so, you can override the default constant with `border-box`\n//\n// To override to the default border-box model, use this code:\n//     $default-background-clip: border-box\n\n$default-background-clip: padding-box !default;\n\n// Clip the background (image and color) at the edge of the padding or border.\n//\n// Legal Values:\n//\n//   * padding-box\n//   * border-box\n//   * text\n\n@mixin background-clip($clip: $default-background-clip) {\n  // webkit and mozilla use the deprecated short [border | padding]\n  $clip: unquote($clip);\n  $deprecated: $clip;\n  @if $clip == padding-box { $deprecated: padding; }\n  @if $clip == border-box { $deprecated: border; }\n  // Support for webkit and mozilla's use of the deprecated short form\n  @include experimental(background-clip, $deprecated,\n    -moz,\n    -webkit,\n    not(-o),\n    not(-ms),\n    not(-khtml),\n    not official\n  );\n  @include experimental(background-clip, $clip,\n    not(-moz),\n    not(-webkit),\n    not(-o),\n    not(-ms),\n    -khtml,\n    official\n  );\n}\n","// Override `$default-background-origin` to change the default.\n\n@import \"shared\";\n\n$default-background-origin: content-box !default;\n\n// Position the background off the edge of the padding, border or content\n//\n// * Possible values:\n//   * `padding-box`\n//   * `border-box`\n//   * `content-box`\n// * browser defaults to `padding-box`\n// * mixin defaults to `content-box`\n\n\n@mixin background-origin($origin: $default-background-origin) {\n  $origin: unquote($origin);\n  // webkit and mozilla use the deprecated short [border | padding | content]\n  $deprecated: $origin;\n  @if $origin == padding-box { $deprecated: padding; }\n  @if $origin == border-box  { $deprecated: border;  }\n  @if $origin == content-box { $deprecated: content; }\n\n  // Support for webkit and mozilla's use of the deprecated short form\n  @include experimental(background-origin, $deprecated,\n    -moz,\n    -webkit,\n    not(-o),\n    not(-ms),\n    not(-khtml),\n    not official\n  );\n  @include experimental(background-origin, $origin,\n    not(-moz),\n    not(-webkit),\n    -o,\n    -ms,\n    -khtml,\n    official\n  );\n}\n","@import \"shared\";\n\n// Cross-browser support for @font-face. Supports IE, Gecko, Webkit, Opera.\n//\n// * $name is required, arbitrary, and what you will use in font stacks.\n// * $font-files is required using font-files('relative/location', 'format').\n//   for best results use this order: woff, opentype/truetype, svg\n// * $eot is required by IE, and is a relative location of the eot file.\n// * $weight shows if the font is bold, defaults to normal\n// * $style defaults to normal, might be also italic\n// * For android 2.2 Compatiblity, please ensure that your web page has\n//   a meta viewport tag.\n// * To support iOS < 4.2, an SVG file must be provided\n//\n// If you need to generate other formats check out the Font Squirrel\n// [font generator](http://www.fontsquirrel.com/fontface/generator)\n//\n\n// In order to refer to a specific style of the font in your stylesheets as \n// e.g. \"font-style: italic;\",  you may add a couple of @font-face includes\n// containing the respective font files for each style and specying\n// respective the $style parameter.\n\n// Order of the includes matters, and it is: normal, bold, italic, bold+italic.\n\n@mixin font-face(\n  $name, \n  $font-files, \n  $eot: false,\n  $weight: false,\n  $style: false\n) {\n  $iefont: unquote(\"#{$eot}?#iefix\");\n  @font-face {\n    font-family: quote($name);\n    @if $eot {\n      src: font-url($eot);\n      $font-files: font-url($iefont) unquote(\"format('eot')\"), $font-files; \n    }\n    src: $font-files;\n    @if $weight {\n      font-weight: $weight;\n    }\n    @if $style {\n      font-style: $style;\n    }\n  }\n}\n","@import \"shared\";\n\n// @doc off\n// Note ----------------------------------------------------------------------\n// Safari, Chrome, and Firefox all support 3D transforms. However,\n// only in the most recent builds. You should also provide fallback 2d support for\n// Opera and IE. IE10 is slated to have 3d enabled, but is currently unreleased.\n// To make that easy, all 2D transforms include an browser-targeting toggle ($only3d)\n// to switch between the two support lists. The toggle defaults to 'false' (2D),\n// and also accepts 'true' (3D). Currently the lists are as follows:\n// 2D: Mozilla, Webkit, Opera, Official\n// 3D: Webkit, Firefox.\n\n// Available Transforms ------------------------------------------------------\n// - Scale (2d and 3d)\n// - Rotate (2d and 3d)\n// - Translate (2d and 3d)\n// - Skew (2d only)\n\n// Transform Parameters ------------------------------------------------------\n// - Transform Origin (2d and 3d)\n// - Perspective (3d)\n// - Perspective Origin (3d)\n// - Transform Style (3d)\n// - Backface Visibility (3d)\n\n// Mixins --------------------------------------------------------------------\n// transform-origin\n//  - shortcuts:  transform-origin2d, transform-origin3d\n//  - helpers:    apply-origin\n// transform\n//  - shortcuts:  transform2d, transform3d\n//  - helpers:    simple-transform, create-transform\n// perspective\n//  - helpers:    perspective-origin\n// transform-style\n// backface-visibility\n// scale\n//  - shortcuts:  scaleX, scaleY, scaleZ, scale3d\n// rotate\n//  - shortcuts:  rotateX, rotateY, rotate3d\n// translate\n//  - shortcuts:  translateX, translateY, translateZ, translate3d\n// skew\n//  - shortcuts:  skewX, skewY\n\n// Defaults ------------------------------------------------------------------\n// @doc on\n\n// The default x-origin for transforms\n$default-origin-x    : 50%                   !default;\n// The default y-origin for transforms\n$default-origin-y    : 50%                   !default;\n// The default z-origin for transforms\n$default-origin-z    : 50%                   !default;\n\n\n// The default x-multiplier for scaling\n$default-scale-x     : 1.25                  !default;\n// The default y-multiplier for scaling\n$default-scale-y     : $default-scale-x      !default;\n// The default z-multiplier for scaling\n$default-scale-z     : $default-scale-x      !default;\n\n\n// The default angle for rotations\n$default-rotate      : 45deg                 !default;\n\n\n// The default x-vector for the axis of 3d rotations\n$default-vector-x    : 1                     !default;\n// The default y-vector for the axis of 3d rotations\n$default-vector-y    : 1                     !default;\n// The default z-vector for the axis of 3d rotations\n$default-vector-z    : 1                     !default;\n\n\n// The default x-length for translations\n$default-translate-x : 1em                   !default;\n// The default y-length for translations\n$default-translate-y :