isplay: inline-block;\n      margin-right: 1.5rem;\n    }\n  }\n}\n@mixin social-outline-button($color) {\nborder: 1px solid $color;\ncolor: $color;\n&:hover {\n  background: $color;\n  color: $white;\n}\n}\n@mixin button-inverse-variant($color, $color-hover: $white) {\n  background-color: rgba($color, 0.2);\n  background-image: none;\n  border-color: rgba($color, 0);\n  &:not(.btn-inverse-light) {\n    color: $color;      \n  }\n  @include hover {\n    color: $color-hover;\n    background-color: $color;\n    border-color: $color;\n  }\n\n  &.focus,\n  &:focus {\n    box-shadow: 0 0 0 3px rgba($color, .5);\n  }\n\n  &.disabled,\n  &:disabled {\n    color: $color;\n    background-color: transparent;\n  }\n\n  &.active,\n  &:active,\n  .show > &.dropdown-toggle {\n    color: $color-hover;\n    background-color: $color;\n    border-color: $color;\n  }\n}\n","// Cards Mixins\n\n@mixin  card-inverse-variant($bg, $border, $color) {\n  background: $bg;\n  border: 1px solid $color;\n  color: $color;\n}","/* Miscellaneous Mixins */\n\n// general transform\n@mixin transform($transforms) {\n    -moz-transform: $transforms;\n      -o-transform: $transforms;\n     -ms-transform: $transforms;\n -webkit-transform: $transforms;\n       transform: $transforms;\n}\n\n// rotate\n@mixin rotate ($deg) {\n@include transform(rotate(#{$deg}deg));\n}\n\n// scale\n@mixin scale($scale) {\n  @include transform(scale($scale));\n}\n// translate\n@mixin translate ($x, $y) {\n@include transform(translate($x, $y));\n}\n// skew\n@mixin skew ($x, $y) {\n@include transform(skew(#{$x}deg, #{$y}deg));\n}\n//transform origin\n@mixin transform-origin ($origin) {\n moz-transform-origin: $origin;\n      -o-transform-origin: $origin;\n     -ms-transform-origin: $origin;\n -webkit-transform-origin: $origin;\n       transform-origin: $origin;\n}\n//Ellipsis\n%ellipsor{\n text-overflow: ellipsis;\n overflow: hidden;\n max-width:100%;\n white-space: nowrap;\n}\n\n// Placeholder\n@mixin placeholder {\n &::-webkit-input-placeholder {\n     @content\n }\n &:-moz-placeholder {\n     @content\n }\n &::-moz-placeholder {\n    @content\n }\n &:-ms-input-placeholder {\n    @content\n }\n}\n\n%ellipsor {\n  text-overflow: ellipsis;\n  overflow: hidden;\n  max-width: 100%;\n  white-space: nowrap;\n  }\n  @mixin ellipsor {\n  text-overflow: ellipsis;\n  overflow: hidden;\n  max-width: 100%;\n  white-space: nowrap;\n}","\n// Sider color variations\n@mixin slider-color-variant($color) {\n\t.noUi-base {\n\t\t.noUi-connect {\n\t\t\tbackground: $color;\n\t\t}\n\n\t\t.noUi-origin {\n\t\t\tbackground: $color;\n\n\t\t\t.noUi-handle {\n\t\t\t\t&:after {\n\t\t\t\t\tbackground: $color;\n\t\t\t\t}\n\n\t\t\t\t.noUi-tooltip {\n\t\t\t\t\tbackground: $color;\n\t\t\t\t\tcolor: $white;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n}","// Pagination variations\n@mixin pagination-variants($color) {\n    .page-item {\n      &.active {\n        .page-link {\n          background: $color;\n          border-color: $color;\n        }\n      }\n      &:hover {\n        .page-link {\n          background: lighten($color,5%);\n          border-color: $color;\n          color: $white;\n        }\n      }\n    }\n}","// popover color variations //\n\n@mixin popover-variant($color) {\n\tborder-color: $color;\n\t.popover-header {\n\t\tbackground: theme-color($color);\n\t\tcolor: $white;\n\t\tborder-bottom: 0;\n\t}\n\t&.bs-popover-top {\n\t\t.arrow {\n\t\t\t&:before,\n\t\t\t&:after {\n\t\t\t\tborder-top-color: theme-color($color);\n\t\t\t}\n\t\t}\n\t}\n\t&.bs-popover-right {\n\t\t.arrow {\n\t\t\t&:before,\n\t\t\t&:after {\n\t\t\t\tborder-right-color: theme-color($color);\n\t\t\t}\n\t\t}\n\t}\n\t&.bs-popover-bottom {\n\t\t.arrow {\n\t\t\t&:before,\n\t\t\t&:after {\n\t\t\t\tborder-bottom-color: theme-color($color);\n\t\t\t}\n\t\t}\n\t}\n\t&.bs-popover-left {\n\t\t.arrow {\n\t\t\t&:before,\n\t\t\t&:after {\n\t\t\t\tborder-left-color: theme-color($color);\n\t\t\t}\n\t\t}\n\t}\n}","// Tooltip color  variations\n\n@mixin tooltip-variant($color) {\n\t.tooltip-inner {\n\t\tbackground:  theme-color($color);\n\t\tcolor: $white;\n\t}\n\t&.bs-tooltip-top {\n    .arrow::before {\n      border-top-color: theme-color($color);\n    }\n  }\n  &.bs-tooltip-right {\n    .arrow::before {\n      border-right-color: theme-color($color);\n    }\n  }\n  &.bs-tooltip-bottom {\n    .arrow::before {\n      border-bottom-color: theme-color($color);\n    }\n  }\n  &.bs-tooltip-left {\n    .arrow::before {\n      border-left-color: theme-color($color);\n    }\n  }\n}","//width mixin\n@mixin make-width($num, $viewport: \"\") {\n  $p: $num + \"%\";\n\n  @if $viewport == \"\" {\n    $viewport: \"-\";\n  } @else {\n    $viewport: \"-\" + $viewport + \"-\";\n  }\n\n  .wd#{$viewport}#{$num} { width: #{$num}px; }\n  .wd#{$viewport}#{$num}p { width: #{$p}; }\n  .mx-wd#{$viewport}#{$num}p { max-width: #{$p}; }\n  .mn-wd#{$viewport}#{$num}p { min-width: #{$p}; }\n\n  .wd#{$viewport}#{$num}-f { width: #{$num}px !important; }\n  .wd#{$viewport}#{$num}p-f { width: #{$p} !important; }\n  .mx-wd#{$viewport}#{$num}p-f { max-width: #{$p} !important; }\n  .mn-wd#{$viewport}#{$num}p-f { min-width: #{$p} !important; }\n}\n\n$num: 5;\n@while $num <= 100 {\n  @include make-width($num);\n  $num: $num + 5;\n}\n\n$num: 150;\n@while $num <= 1000 {\n  .wd-#{$num} { width: #{$num}px; }\n  .wd-#{$num}-f { width: #{$num}px !important; }\n  $num: $num + 50;\n}\n\n@mixin do-make-width($viewport, $num, $max, $plus) {\n  @while $num <= $max {\n    @include make-width($num,$viewport);\n    $num: $num + $plus;\n  }\n}\n\n@media (min-width: 480px) {\n  @include do-make-width(\"xs\",5,100,5);\n  @include do-make-width(\"xs\",150,1000,50);\n\n  .wd-xs-auto { width: auto; }\n  .wd-xs-auto-f { width: auto !important; }\n}\n\n@include media-breakpoint-up(sm) {\n  @include do-make-width(\"sm\",5,100,5);\n  @include do-make-width(\"sm\",150,1000,50);\n\n  .wd-sm-auto { width: auto; }\n  .wd-sm-auto-f { width: auto !important; }\n}\n\n@include media-breakpoint-up(md) {\n  @include do-make-width(\"md\",5,100,5);\n  @include do-make-width(\"md\",150,1000,50);\n\n  .wd-md-auto { width: auto; }\n  .wd-md-auto-f { width: auto !important; }\n\n  //Custom\n  .wd-md-120 { width: 120px; }\n}\n\n@include media-breakpoint-up(lg) {\n  @include do-make-width(\"lg\",5,100,5);\n  @include do-make-width(\"lg\",150,1000,50);\n\n  .wd-lg-auto { width: auto; }\n  .wd-lg-auto-f { width: auto !important; }\n}\n\n@include media-breakpoint-up(xl) {\n  @include do-make-width(\"xl\",5,100,5);\n  @include do-make-width(\"xl\",150,1000,50);\n\n  .wd-xl-auto { width: auto; }\n  .wd-xl-auto { width: auto !important; }\n}","@each $color, $value in $social-colors {\n  .bg-#{$color} {\n    background: social-color($color);\n  }\n}\n\n@each $color, $value in $theme-gradient-colors {\n  .bg-gradient-#{$color} {\n    background: $value;\n  }\n}","// Reste styles\n\nbody {\n  margin: 0;\n  padding: 0;\n}\n\n.form-control {\n  &,\n  &:focus {\n    -webkit-box-shadow: none;\n    -moz-box-shadow: none;\n    box-shadow: none;\n    outline: none;\n  }\n}\n\na,\ndiv,\nh1,\nh2,\nh3,\nh4,\nh5,\nh6,\np,\nspan {\n  text-shadow: none;\n}\n\n[type=button]:focus,\na:active,\na:focus,\na:visited,\nbutton::-moz-focus-inner,\ninput[type=reset]::-moz-focus-inner,\ninput[type=button]::-moz-focus-inner,\ninput[type=submit]::-moz-focus-inner,\ninput[type=file]>input[type=button]::-moz-focus-inner,\nselect::-moz-focus-inner {\n  outline: 0;\n}\n\ninput,\n.form-control:focus,\ninput:focus,\nselect:focus,\ntextarea:focus,\nbutton:focus {\n  outline: none;\n  outline-width: 0;\n  outline-color: transparent;\n  box-shadow: none;\n  outline-style: none;\n}\n\ntextarea {\n  resize: none;\n  overflow-x: hidden;\n}\n\n.btn,\n.btn-group.open .dropdown-toggle,\n.btn:active,\n.btn:focus,\n.btn:hover,\n.btn:visited,\na,\na:active,\na:checked,\na:focus,\na:hover,\na:visited,\nbody,\nbutton,\nbutton:active,\nbutton:hover,\nbutton:visited,\ndiv,\ninput,\ninput:active,\ninput:hover,\ninput:focus